+template <class vertex, class F>
+inline void visit_neighbors(vertex& row, uintE id, F visit, const uintE*) {
+  for (uintT j = 0, d = row.getOutDegree(); j < d; ++j)
+    visit(row.getOutNeighbor(j));
+}
+
+template <class vertex, class F>
+inline void visit_neighbors(vertex& row, uintE id, F visit, const uchar*) {
+  auto apply = [&](uintE, uintE neighbor) {
+    visit(neighbor);
+    return false;
+  };
