+
+template <class vertex, class F>
+inline void visit_neighbors(vertex& row, uintE id, F visit) {
+  visit_neighbors(row, id, visit, row.getOutNeighbors());
+}
+// Append a worker's discoveries to the shared queue in contiguous blocks.
+struct queue_writer {
+  uintE* queue;
+  size_t& end;
+  uintE buffer[128];
+  size_t count = 0;
+  queue_writer(uintE* q, size_t& tail) : queue(q), end(tail) {}
+  void flush() {
+    if (!count) return;
+    size_t pos = __atomic_fetch_add(&end, count, __ATOMIC_RELAXED);
+    std::copy(buffer, buffer + count, queue + pos);
+    count = 0;
+  }
+  void push(uintE v) {
+    buffer[count++] = v;
+    if (count == 128) flush();
+  }
+  ~queue_writer() { flush(); }
+};
+
+
+struct member_row {
+  const uintE* ids;
+  uintT size;
+};
+
+// Uniform consecutive rows can be addressed from one base per block. Ragged
+// blocks use the original rows. Both cases describe the same incidence lists.
+class member_rows {
+  static constexpr size_t block_size = 64;
+  symmetricVertex* edges;
+  std::vector<member_row> blocks;
+
+public:
+  member_rows(symmetricVertex* h, size_t n, int workers)
+    : edges(h), blocks((n + block_size - 1) / block_size) {
+    #pragma omp parallel for num_threads(workers) if(workers > 1) schedule(static)
+    for (size_t b = 0; b < blocks.size(); ++b) {
+      size_t start = b*block_size;
+      size_t end = std::min(start + block_size, n);
+      const uintE* first = edges[start].getOutNeighbors();
+      uintT size = edges[start].getOutDegree();
+      uintptr_t expected = reinterpret_cast<uintptr_t>(first);
+      for (size_t e = start+1; e < end; ++e) {
+        expected += size*sizeof(uintE);
+        if (edges[e].getOutDegree() != size ||
+            reinterpret_cast<uintptr_t>(edges[e].getOutNeighbors()) != expected) {
+          first = nullptr;
+          break;
+        }
+      }
+      blocks[b] = {first,size};
+    }
+  }
+
+  member_row get(uintE e) const {
+    member_row block = blocks[e / block_size];
+    if (block.ids) return {block.ids + (e % block_size)*block.size, block.size};
+    return {edges[e].getOutNeighbors(), edges[e].getOutDegree()};
+  }
+};
+
+template <class F>
+inline void visit_batch(const member_row* batch, size_t count, F visit) {
+  for (size_t i = 0; i < count; ++i)
+    for (size_t j = 0; j < batch[i].size; ++j) visit(batch[i].ids[j]);
+}
+
+template <bool concurrent, class F>
+size_t claim_edges(hypergraph<symmetricVertex>& graph, const member_rows& members,
+                   unsigned char* live, const uintE* queue, size_t begin, size_t end, F visit) {
+  member_row batch[64];
+  size_t count = 0, processed = 0;
+  for (size_t i = begin; i < end; ++i) {
+    uintE v = queue[i];
+    visit_neighbors(graph.V[v], v, [&](uintE e) {
+      if (concurrent) {
+        if (!__atomic_load_n(live + e, __ATOMIC_RELAXED) ||
+            !__atomic_exchange_n(live + e, 0, __ATOMIC_RELAXED)) return;
+      } else {
+        if (!live[e]) return;
+        live[e] = 0;
+      }
+      member_row row = members.get(e);
+      __builtin_prefetch(row.ids);
+      batch[count++] = row;
+      if (count == 64) {
+        visit_batch(batch, count, visit);
+        processed += count;
+        count = 0;
+      }
+    });
+  }
+  visit_batch(batch, count, visit);
+  return processed + count;
+}
+
+template <class vertex, class Degree>
+bool survives(vertex& row, uintE id, const Degree* degree, uintE level, const uintE*) {
+  for (uintT j = 0; j < row.getOutDegree(); ++j)
+    if (degree[row.getOutNeighbor(j)] <= level) return false;
+  return true;
+}
+
+template <class vertex, class Degree>
+bool survives(vertex& row, uintE id, const Degree* degree, uintE level, const uchar*) {
+  bool ok = true;
+  visit_neighbors(row, id, [&](uintE v) { ok &= degree[v] > level; });
+  return ok;
+}
+
+// A sequential scan can retire more vertices immediately, as each later row
+// sees all deletions from earlier rows. Recount the survivors once to restore
+// exact degrees before returning to sparse queue processing.
+template <class vertex, class Degree>
+void sequential_sweep(hypergraph<vertex>& graph, Degree* degree, uintE level,
+                      unsigned char* live, uintE* queue, size_t& head, size_t& tail) {
+  const size_t n = graph.nv, end = tail;
+  for (size_t i = head; i < end; ++i) {
+    uintE v = queue[i];
+    visit_neighbors(graph.V[v], v, [&](uintE e) { live[e] = 0; });
+  }
+  for (size_t v = 0; v < n; ++v) {
+    if (degree[v] <= level) {
+      degree[v] = 0;
+      continue;
+    }
+    uintE count = 0;
+    visit_neighbors(graph.V[v], v, [&](uintE e) { count += live[e]; });
+    degree[v] = count;
+    if (count <= level) {
+      queue[tail++] = v;
+      degree[v] = 0;
+      visit_neighbors(graph.V[v], v, [&](uintE e) { live[e] = 0; });
+    }
+  }
+  head = tail;
+  if (tail == end || tail == n) return;
+  for (size_t v = 0; v < n; ++v) {
+    if (!degree[v]) continue;
+    uintE count = 0;
+    visit_neighbors(graph.V[v], v, [&](uintE e) { count += live[e]; });
+    degree[v] = count;
+    if (count <= level) queue[tail++] = v;
+  }
+}
+
+template <bool rebuild, class Degree>
+inline void update_block(Degree* degree, const Degree* count, size_t len,
+                         size_t base, uintE level, queue_writer& out) {
+  for (size_t i = 0; i < len; ++i) {
+    uintE old = degree[i];
+    uintE d = rebuild ? count[i] : old-count[i];
+    degree[i] = d;
+    if (old > level && d <= level) out.push(base+i);
+  }
+}
+
+#ifdef __SSE2__
+template <bool rebuild>
+inline void update_block(unsigned char* degree, const unsigned char* count, size_t len,
+                         size_t base, uintE level, queue_writer& out) {
+  const __m128i sign = _mm_set1_epi8(char(0x80));
+  const __m128i threshold = _mm_set1_epi8(char(level ^ 0x80));
+  size_t i = 0;
+  for (; i+16 <= len; i+=16) {
+    __m128i old = _mm_loadu_si128(reinterpret_cast<const __m128i*>(degree+i));
+    __m128i c = _mm_loadu_si128(reinterpret_cast<const __m128i*>(count+i));
+    __m128i d = rebuild ? c : _mm_sub_epi8(old,c);
+    _mm_storeu_si128(reinterpret_cast<__m128i*>(degree+i),d);
+    __m128i before = _mm_cmpgt_epi8(_mm_xor_si128(old,sign),threshold);
+    __m128i after = _mm_cmpgt_epi8(_mm_xor_si128(d,sign),threshold);
+    unsigned mask = _mm_movemask_epi8(_mm_andnot_si128(after,before));
+    while (mask) {
+      out.push(base+i+__builtin_ctz(mask));
+      mask &= mask-1;
+    }
+  }
+  update_block<rebuild,unsigned char>(degree+i,count+i,len-i,base+i,level,out);
+}
+#endif
