+// For intermediate waves count degree losses privately. For wide waves count
+// the surviving incidences instead. Both yield the exact new residual degree.
+template <bool rebuild, class vertex, class Degree>
+bool batch_wave(hypergraph<vertex>& graph, uintE level, Degree* degree,
+                unsigned char* live, uintE* queue, size_t begin, size_t end,
+                size_t& tail, int workers, Degree* partial, size_t stride, size_t& live_count,
+                const member_rows& members) {
+  const size_t n = graph.nv, width = end - begin;
+  size_t surviving_edges = 0, removed_edges = 0;
+  #pragma omp parallel num_threads(workers) if(workers > 1)
+  {
+    const int t = omp_get_thread_num(), nt = omp_get_num_threads();
+    Degree* local = partial + stride*t;
+    std::fill(local, local+n, Degree(0));
+    if (rebuild) {
+      #pragma omp for reduction(+:surviving_edges) schedule(static)
+      for (long e = 0; e < graph.nh; ++e) {
+        if (!live[e]) continue;
+        auto& row = graph.H[e];
+        if (survives(row, e, degree, level, row.getOutNeighbors())) {
+          ++surviving_edges;
+          visit_neighbors(row, e, [&](uintE u) { ++local[u]; });
+        } else live[e] = 0;
+      }
+    } else {
+      auto lost = [&](uintE u) { ++local[u]; };
+      size_t removed = nt == 1 ? claim_edges<false>(graph, members, live, queue, begin, end, lost)
+        : claim_edges<true>(graph, members, live, queue, begin+width*t/nt, begin+width*(t+1)/nt, lost);
+      #pragma omp atomic update
+      removed_edges += removed;
+      #pragma omp barrier
+    }
+    if (!rebuild || surviving_edges > level) {
+      queue_writer out(queue, tail);
+      #pragma omp for schedule(static)
+      for (size_t base = 0; base < n; base += 512) {
+        size_t len = std::min<size_t>(512, n-base);
+        Degree count[512];
+        std::copy_n(partial + base, len, count);
+        for (int j = 1; j < nt; ++j) {
+          const Degree* src = partial + stride*j + base;
+          for (size_t i = 0; i < len; ++i) count[i] += src[i];
+        }
+        update_block<rebuild>(degree+base,count,len,base,level,out);
+      }
+    }
+  }
+  live_count = rebuild ? surviving_edges : live_count-removed_edges;
+  return rebuild && surviving_edges <= level;
+}
